/**
 * @suppress
 */
public object FfiConverterTypeEngytita: FfiConverter<Engytita, Pointer> {

    override fun lower(value: Engytita): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): Engytita {
        return Engytita(value)
    }

    override fun read(buf: ByteBuffer): Engytita {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: Engytita) = 8UL

    override fun write(value: Engytita, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}


