/**
 * @suppress
 */
public object FfiConverterTypePairingSession: FfiConverter<PairingSession, Pointer> {

    override fun lower(value: PairingSession): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): PairingSession {
        return PairingSession(value)
    }

    override fun read(buf: ByteBuffer): PairingSession {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: PairingSession) = 8UL

    override fun write(value: PairingSession, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



/**
 * Opaque peer handle (16 bytes). Not a public key and not a secret.
 */
