    var `bytes`: kotlin.ByteArray
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypePeerId: FfiConverterRustBuffer<PeerId> {
    override fun read(buf: ByteBuffer): PeerId {
