/**
 * Local willingness to engage in sessions.
 */

enum class AvailabilityMode {
    
    /**
     * Resolution still works; session request/accept are refused.
     */
    OFF,
    /**
     * Any paired contact may request / accept.
     */
    CONTACTS_ONLY;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeAvailabilityMode: FfiConverterRustBuffer<AvailabilityMode> {
    override fun read(buf: ByteBuffer) = try {
        AvailabilityMode.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: AvailabilityMode) = 4UL

    override fun write(value: AvailabilityMode, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







/**
 * Errors crossing the FFI boundary (no secret material in messages).
 */
sealed class EngytitaException: kotlin.Exception() {
    
    class InvalidInput(
        
        val `reason`: kotlin.String
        ) : EngytitaException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Pairing(
        
        val `reason`: kotlin.String
        ) : EngytitaException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Consent(
        
        val `reason`: kotlin.String
        ) : EngytitaException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<EngytitaException> {
        override fun lift(error_buf: RustBuffer.ByValue): EngytitaException = FfiConverterTypeEngytitaError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeEngytitaError : FfiConverterRustBuffer<EngytitaException> {
    override fun read(buf: ByteBuffer): EngytitaException {
        

        return when(buf.getInt()) {
            1 -> EngytitaException.InvalidInput(
                FfiConverterString.read(buf),
                )
            2 -> EngytitaException.Pairing(
                FfiConverterString.read(buf),
                )
            3 -> EngytitaException.Consent(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: EngytitaException): ULong {
        return when(value) {
            is EngytitaException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is EngytitaException.Pairing -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is EngytitaException.Consent -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: EngytitaException, buf: ByteBuffer) {
        when(value) {
            is EngytitaException.InvalidInput -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is EngytitaException.Pairing -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is EngytitaException.Consent -> {
                buf.putInt(3)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Sans-I/O pairing step for the host to handle.
 */
sealed class PairingEvent {
    
    object AwaitingMessage : PairingEvent()
    
    
    data class SendMessage(
        val `data`: kotlin.ByteArray) : PairingEvent() {
        companion object
    }
    
    /**
     * Six decimal digits as a string (e.g. `"483984"`). Confirm out-of-band.
     */
    data class ConfirmSas(
        val `digits`: kotlin.String) : PairingEvent() {
        companion object
    }
    
    /**
     * Peer was stored in the engine; only the opaque id is returned.
     */
    data class Complete(
        val `peerId`: PeerId) : PairingEvent() {
        companion object
    }
    
    data class Failed(
        val `message`: kotlin.String) : PairingEvent() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypePairingEvent : FfiConverterRustBuffer<PairingEvent>{
    override fun read(buf: ByteBuffer): PairingEvent {
        return when(buf.getInt()) {
            1 -> PairingEvent.AwaitingMessage
            2 -> PairingEvent.SendMessage(
                FfiConverterByteArray.read(buf),
                )
            3 -> PairingEvent.ConfirmSas(
                FfiConverterString.read(buf),
                )
            4 -> PairingEvent.Complete(
                FfiConverterTypePeerId.read(buf),
                )
            5 -> PairingEvent.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: PairingEvent) = when(value) {
        is PairingEvent.AwaitingMessage -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is PairingEvent.SendMessage -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`data`)
            )
        }
        is PairingEvent.ConfirmSas -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`digits`)
            )
        }
        is PairingEvent.Complete -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePeerId.allocationSize(value.`peerId`)
            )
        }
        is PairingEvent.Failed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
    }

    override fun write(value: PairingEvent, buf: ByteBuffer) {
        when(value) {
            is PairingEvent.AwaitingMessage -> {
                buf.putInt(1)
                Unit
            }
            is PairingEvent.SendMessage -> {
                buf.putInt(2)
                FfiConverterByteArray.write(value.`data`, buf)
                Unit
            }
            is PairingEvent.ConfirmSas -> {
                buf.putInt(3)
                FfiConverterString.write(value.`digits`, buf)
                Unit
            }
            is PairingEvent.Complete -> {
                buf.putInt(4)
                FfiConverterTypePeerId.write(value.`peerId`, buf)
                Unit
            }
            is PairingEvent.Failed -> {
                buf.putInt(5)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




